package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class CatalogCard {
 static LinearLayout create(Context c,String title,String cover){LinearLayout row=new LinearLayout(c);row.setGravity(android.view.Gravity.CENTER_VERTICAL);int p=NativeSheet.dp(c,10);row.setPadding(p,p,p,p);row.setBackground(AppStyle.shape(row,0xff201c2a,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,NativeSheet.dp(c,8));row.setLayoutParams(lp);ImageView image=new ImageView(c);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(AppStyle.shape(image,0xff363044,10));image.setClipToOutline(true);row.addView(image,new LinearLayout.LayoutParams(NativeSheet.dp(c,68),NativeSheet.dp(c,90)));AccountImageLoader.load(image,cover);TextView name=NativeSheet.text(c,title,15,0xfff3effa);name.setPadding(p,0,p,0);name.setMaxLines(Integer.MAX_VALUE);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));row.setContentDescription("Selecionar "+title);return row;}
 static LinearLayout result(Context c,org.json.JSONObject item,boolean media,int type,String hint){String title=CatalogSelection.name(item);LinearLayout row=create(c,title,media?item.optString("capa"):item.optString("cover_image",item.optString("background_image")));TextView name=(TextView)row.getChildAt(1);row.removeView(name);name.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));LinearLayout info=new LinearLayout(c);info.setOrientation(LinearLayout.VERTICAL);info.addView(name);TextView meta=NativeSheet.text(c,CatalogSelection.meta(item,media,type),12,0xffb4a6c7);meta.setPadding(NativeSheet.dp(c,10),0,0,0);info.addView(meta);TextView state=NativeSheet.text(c,hint,12,0xffba9eff);state.setPadding(NativeSheet.dp(c,10),NativeSheet.dp(c,6),0,0);info.addView(state);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));if(hint.startsWith("Já")||hint.startsWith("✓")){state.setTypeface(null,android.graphics.Typeface.BOLD);state.setBackground(AppStyle.shape(state,NativeTheme.soft(c),8));}row.setContentDescription(title+" · "+meta.getText()+" · "+hint);return row;}
}
